import { ReactElement } from 'react';

import { StoryFn } from '@storybook/react';

import { Chart } from '../../../Chart.js';
import { Axis, Line } from '../../../components/index.js';
import useChartProps from '../../../hooks/useChartProps.js';
import { bindWithProps } from '../../../test-utils/index.js';

export default {
  title: 'React Spectrum Charts 2/Axis/Regressions/Time Axis Annotations',
  tags: ['alpha'],
  component: Chart,
  parameters: {
    regression: {
      description:
        'Point and range annotations used invalid coordinates with Date values and custom time fields, and hiding default time labels did not hide them.',
      pr: 1129,
    },
  },
};

const TimeAxisAnnotationsStory: StoryFn<typeof Chart> = (args): ReactElement => {
  const chartProps = useChartProps(args);
  return (
    <Chart {...chartProps}>
      <Axis
        position="bottom"
        labelFormat="time"
        hideDefaultLabels
        axisAnnotations={[
          {
            options: [
              { id: 'point', color: 'magenta-600' },
              { id: 'range', color: 'celery-600' },
            ],
          },
        ]}
      />
      <Axis position="left" grid />
      <Line dimension="timestamp" interpolate="linear" />
    </Chart>
  );
};

const DateValuesWithHiddenLabels = bindWithProps(TimeAxisAnnotationsStory);
DateValuesWithHiddenLabels.args = {
  data: [24, 38, 30, 52, 44].map((value, index) => ({
    timestamp: new Date(Date.UTC(2026, 0, index + 1)),
    value,
    annotations: [...(index === 0 ? ['point'] : []), ...(index >= 2 ? ['range'] : [])],
  })),
  width: 560,
  height: 280,
  animations: false,
  renderer: 'svg',
};

export { DateValuesWithHiddenLabels };
